import { Component, input } from '@angular/core';
import { NzStatisticModule } from 'ng-zorro-antd/statistic';

/** hrm-statistic — chỉ số dashboard, bọc nz-statistic. */
@Component({
  selector: 'hrm-statistic',
  imports: [NzStatisticModule],
  template: `
    <nz-statistic
      [nzValue]="value()"
      [nzTitle]="title()"
      [nzPrefix]="prefix()"
      [nzSuffix]="suffix()"
      [nzValueStyle]="valueColor() ? { color: valueColor()! } : {}"></nz-statistic>
  `,
  host: { class: 'hrm-statistic' },
})
export class HrmStatistic {
  readonly value = input<string | number>(0);
  readonly title = input('');
  readonly prefix = input('');
  readonly suffix = input('');
  readonly valueColor = input<string | null>(null);
}
